{
  "findings": [
    {
      "check_id": "CKV_AWS_123",
      "title": "Target group using an unencrypted protocol",
      "resource": "aws_lb_target_group.pass",
      "severity": "HIGH",
      "explanation": "The target group is configured to use the TCP protocol on port 80, which does not provide encryption for data in transit. This can expose sensitive data to interception or tampering."
    }
  ],
  "patched_code": "resource \"aws_lb_target_group\" \"pass\" {\n  name        = \"tf-example-lb-alb-tg\"\n  target_type = \"alb\"\n  port        = 443\n  protocol    = \"TLS\"\n  vpc_id      = aws_vpc.main.id\n}\n",
  "fix_summary": "Updated the target group to use the TLS protocol on port 443 to ensure encryption for data in transit."
}
